package main

import (
	"bytes"
	"encoding/gob"
	"strings"

	"github.com/coocood/freecache"
)

const (
	defaultCacheSize = 1000 << 20  // 1000 MB cache
	defaultExpiry    = 120 * 3600  // 120 hours cache expiry
	stringSeparator  = "<>"        // Assuming the separator wont be used in any case.
)

// Cache objects.
type Cache struct {
	fc *freecache.Cache
}

type GeneralCacheItem struct {
	Value interface{}
}

// NewCache will create a new freecache
func NewCache() Cache {
	return Cache{fc: freecache.NewCache(defaultCacheSize)}
}

// Set a string value to cache.
func (c *Cache) SetString(key string, val ...string) error {
	var value = strings.Join(val, stringSeparator)
	return c.setWithExpiry(key, []byte(value), int(defaultExpiry))
}

func (c *Cache) setWithExpiry(key string, val []byte, expiry int) error {
	return c.fc.Set([]byte(key), val, expiry)
}

// Get a string value from cache.
func (c *Cache) GetString(key string) ([]string, error) {
	val, err := c.fc.Get([]byte(key))
	if err != nil {
		return nil, err
	}

	return strings.Split(string(val), stringSeparator), nil
}

// Set a generic cache value.
// These are about 100 micro-seconds (3 times) slower
// than the string cache above. It's slower because of
// encoding and decoding
func (c *Cache) Set(key string, value interface{}) error {
	var valueBytesBuffer bytes.Buffer

	// gob can only encode struct items.
	// It can't encode arrays properly
	cacheItem := GeneralCacheItem{value}

	enc := gob.NewEncoder(&valueBytesBuffer)
	err := enc.Encode(cacheItem)
	if err != nil {
		return err
	}

	return c.fc.Set([]byte(key), valueBytesBuffer.Bytes(), int(defaultExpiry))
}

// Get a value from cache.
func (c *Cache) Get(key string) (interface{}, error) {
	valueBytes, err := c.fc.Get([]byte(key))
	if err != nil {
		return nil, err
	}

	var cacheItem GeneralCacheItem

	dec := gob.NewDecoder(bytes.NewReader(valueBytes))
	err = dec.Decode(&cacheItem)
	if err != nil {
		return nil, err
	}

	return cacheItem.Value, nil
}

// Delete a value from cache.
func (c *Cache) Delete(key string) (bool, error) {
	affected := c.fc.Del([]byte(key))
	return affected, nil
}

// Clear everything in the cache.
func (c *Cache) Clear() {
	c.fc.Clear()
}

package main

import (
	"fmt"
	"log"
	"os"
	"path"
	"runtime"
	"strings"
	"time"

	"github.com/knadh/stuffbin"
)

func initConfig(cfg appConfig) *config {
	toDownload := make(map[string]bool)
	schemes := strings.Split(cfg.DownloadEnabledSchemes, ",")

	for _, scheme := range schemes {
		s := strings.TrimSpace(scheme)

		if s != "" {
			if !isValidSchemeIdentifier(s) {
				panic(fmt.Sprintf("%s is not a valid libvarnam supported scheme", s))
			}

			toDownload[s] = true
		}
	}

	return &config{upstream: cfg.UpstreamURL, schemesToDownload: toDownload,
		syncInterval: time.Duration(cfg.SyncInterval)}
}

func (c *config) setDownloadStatus(langCode string, status bool) error {
	if !isValidSchemeIdentifier(langCode) {
		return fmt.Errorf("%s is not a valid libvarnam supported scheme", langCode)
	}

	c.schemesToDownload[langCode] = status

	if status {
		// when varnamd was started without any langcodes to sync, the dispatcher won't be running
		// in that case, we need to start the dispatcher since we have a new lang code to download now
		startSyncDispatcher()
	}

	return nil
}

func getConfigDir() string {
	if runtime.GOOS == "windows" {
		return path.Join(os.Getenv("localappdata"), ".varnamd")
	}

	return path.Join(os.Getenv("HOME"), ".varnamd")
}

// initVFS initializes the stuffbin virtual FileSystem to provide
// access to bunded static assets to the app.
func initVFS() (stuffbin.FileSystem, error) {
	files := []string{
		"ui:/",
	}

	binPath, err := os.Executable()
	if err != nil {
		return nil, err
	}

	fs, err := stuffbin.UnStuff(binPath)
	if err != nil {
		log.Printf("unable to initialize embedded filesystem: %v", err)
		log.Printf("using local filesystem")

		fs, err = stuffbin.NewLocalFS("/", files...)
		if err != nil {
			return nil, err
		}
	}

	return fs, nil
}

func initAppConfig() (appConfig, error) {
	var config appConfig
	// Read configuration using Koanf.
	if err := kf.Unmarshal("app", &config); err != nil {
		return config, err
	}

	// If address is empty run on localhost port 8080.
	if config.Address == "" {
		config.Address = fmt.Sprintf("%s:%d", kf.String("host"), kf.Int("p"))
	}

	if config.EnableSSL && (config.CertFilePath == "" || config.KeyFilePath == "") {
		config.EnableSSL = false
	}

	if config.SyncInterval < 1*time.Second {
		config.SyncInterval = 30 * time.Second
	}

	if config.UpstreamURL == "" {
		config.UpstreamURL = "https://api.varnamproject.com"
	}

	return config, nil
}

package main

import (
	"fmt"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/labstack/echo/v4"
	"github.com/varnamproject/govarnam/govarnamgo"
)

const defaultChanSize = 1000

var (
	learnChannels map[string]chan string
	trainChannel  map[string]chan trainArgs
)

// initChannels method will initialize learn and train channels.
func (app *App) initChannels() {
	learnChannels = make(map[string]chan string)
	trainChannel = make(map[string]chan trainArgs)

	for _, scheme := range schemeDetails {
		learnChannels[scheme.Identifier] = make(chan string, defaultChanSize)
		trainChannel[scheme.Identifier] = make(chan trainArgs, defaultChanSize)

		handle, err := govarnamgo.InitFromID(scheme.Identifier)
		if err != nil {
			app.log.Fatal("Unable to initialize varnam for lang", scheme.LangCode)
		}

		go app.listenForWords(scheme.Identifier, handle)
	}
}

func (app *App) listenForWords(lang string, handle *govarnamgo.VarnamHandle) {
	for {
		select {
		case word := <-learnChannels[lang]:
			if err := handle.Learn(strings.TrimSpace(word), 0); err != nil {
				app.log.Printf("Failed to learn %s. %s\n", word, err.Error())
			}
		case args := <-trainChannel[lang]:
			if err := handle.Train(strings.TrimSpace(args.Pattern), strings.TrimSpace(args.Word)); err != nil {
				app.log.Printf("error training word: %s, pattern: %s, err:%s", args.Word, args.Pattern, err.Error())
			}
		}
	}
}

func learnWordsFromFile(c echo.Context, langCode string, fileToLearn string, removeFile bool) {
	c.Response().WriteHeader(http.StatusOK)

	start := time.Now()

	sendOutput := func(msg string) {
		_, _ = c.Response().Write([]byte(msg))
		c.Response().Flush()
	}

	sendOutput(fmt.Sprintf("Learning from %s\n", fileToLearn))

	_, _ = getOrCreateHandler(langCode, func(handle *govarnamgo.VarnamHandle) (data interface{}, err error) {
		learnStatus, verr := handle.LearnFromFile(fileToLearn)
		end := time.Now()

		if verr != nil {
			sendOutput(fmt.Sprintf("Error learning: '%s'\n", verr.Error()))
		} else {
			sendOutput(fmt.Sprintf("Finished Learning. TotalWords: %d, Failed: %d. Took %s\n", learnStatus.TotalWords, learnStatus.FailedWords, end.Sub(start)))
		}

		if removeFile {
			if err = os.Remove(fileToLearn); err != nil {
				sendOutput(fmt.Sprintf("Error deleting '%s'. %s\n", fileToLearn, err.Error()))
			}
		}

		return
	})
}

func importLearningsFromFile(c echo.Context, langCode string, fileToImport string, removeFile bool) error {
	c.Response().WriteHeader(http.StatusOK)

	start := time.Now()

	sendOutput := func(msg string) {
		_, _ = c.Response().Write([]byte(msg))
		c.Response().Flush()
	}

	sendOutput(fmt.Sprintf("Importing from %s\n", fileToImport))

	var importError error

	_, _ = getOrCreateHandler(langCode, func(handle *govarnamgo.VarnamHandle) (data interface{}, err error) {
		err = handle.Import(fileToImport)
		end := time.Now()

		if err != nil {
			importError = err
		} else {
			sendOutput(fmt.Sprintf("Import completed. Took %s\n", end.Sub(start)))
		}

		if removeFile {
			if err = os.Remove(fileToImport); err != nil {
				sendOutput(fmt.Sprintf("Error deleting '%s'. %s\n", fileToImport, err.Error()))
			}
		}
		return
	})

	return importError
}

package main

import (
	"encoding/gob"
	"fmt"
	"log"
	"os"
	"runtime"
	"time"

	flag "github.com/spf13/pflag"

	"github.com/knadh/koanf"
	"github.com/knadh/koanf/parsers/toml"
	"github.com/knadh/koanf/providers/file"
	"github.com/knadh/koanf/providers/posflag"
	"github.com/knadh/stuffbin"
)

type userConfig map[string]string

const (
	downloadPageSize = 100
)

var (
	kf = koanf.New(".")

	varnamdConfig         *config // config instance used across the application
	syncDispatcherRunning bool
	startedAt             time.Time
	buildVersion          string
	buildDate             string
	maxHandleCount        int
	authEnabled           bool

	// User accounts are stored here.
	users map[string]userConfig
)

type appConfig struct {
	Address string

	EnableInternalApis bool   `koanf:"enable-internal-api"` // internal APIs are not exposed to public
	EnableSSL          bool   `koanf:"enable-ssl"`
	CertFilePath       string `koanf:"cert-path"`
	KeyFilePath        string `koanf:"key-file-path"`

	DownloadEnabledSchemes string        `koanf:"download-enabled-schemes"`
	SyncInterval           time.Duration `koanf:"sync-interval"`
	UpstreamURL            string        `koanf:"upstream-url"`
}

// App is a singleton to share across handlers.
type App struct {
	cache Cache
	log   *log.Logger
	fs    stuffbin.FileSystem
}

// varnamd configurations
// this is populated from various command line flags
type config struct {
	upstream          string
	schemesToDownload map[string]bool
	syncInterval      time.Duration
}

func init() {
	// Set max processors to number of CPUs to maximize performance.
	runtime.GOMAXPROCS(runtime.NumCPU())

	//  Setup flags to read from user to start the application.
	// Initialize 'config' flagset.
	flagSet := flag.NewFlagSet("config", flag.ContinueOnError)
	flagSet.Usage = func() {
		log.Fatal(flagSet.FlagUsages())
	}

	// Create  config flag to read 'config.toml' from user.
	flagSet.String("config", "config.toml", "Path to the TOML configuration file")

	flagSet.Int("p", 8080, "Run daemon in specified port")
	flagSet.String("host", "", "Host for the varnam daemon server")

	// Create flag for version check.
	flagSet.Bool("version", false, "Current version of the build")

	err := flagSet.Parse(os.Args[1:])
	if err != nil {
		log.Fatalf("error parsing flags: %v", err)
	}

	// Load commandline params user given.
	if err = kf.Load(posflag.Provider(flagSet, ".", kf), nil); err != nil {
		log.Fatal(err.Error())
	}

	// Handle --version flag. Print build version, build date and die.
	if kf.Bool("version") {
		fmt.Printf("Commit: %v\nBuild: %v\n", buildVersion, buildDate)
		os.Exit(0)
	}

	// Load the config file.
	log.Printf("reading config: %s", kf.String("config"))

	if err = kf.Load(file.Provider(kf.String("config")), toml.Parser()); err != nil {
		log.Printf("error reading config: %v", err)
	}
}

func syncRequired() bool {
	return len(varnamdConfig.schemesToDownload) > 0
}

// Starts the sync process only if it is not running
func startSyncDispatcher() {
	if syncRequired() && !syncDispatcherRunning {
		sync := newSyncDispatcher(varnamdConfig.syncInterval / time.Second)
		sync.start()
		sync.runNow() // run one round of sync immediatly rather than waiting for the next interval to occur

		syncDispatcherRunning = true
	}
}

func main() {
	config, err := initAppConfig()
	if err != nil {
		log.Fatal(err.Error())
	}

	maxHandleCount = kf.Int("app.max-handles")
	if maxHandleCount <= 0 {
		maxHandleCount = 10
	}

	authEnabled = kf.Bool("app.accounts-enabled")
	if authEnabled {
		if err = kf.Unmarshal("users", &users); err != nil {
			log.Fatal(err.Error())
		}
	}

	varnamdConfig = initConfig(config)
	startedAt = time.Now()

	log.Printf("varnamd %s-%s", buildVersion, buildDate)

	fs, err := initVFS()
	if err != nil {
		log.Fatal(err.Error())
	}

	app := &App{
		cache: NewCache(),
		log:   log.New(os.Stdout, "", log.Ldate|log.Ltime|log.Lshortfile),
		fs:    fs,
	}

	gob.Register(advancedTransliterationResponse{})

	startSyncDispatcher()
	startDaemon(app, config)
}

package main

import (
	"encoding/base64"
	"net/http"
	"strings"

	"github.com/labstack/echo/v4"
	"github.com/labstack/echo/v4/middleware"
)

func startDaemon(app *App, cfg appConfig) {
	initLanguageChannels()
	app.initChannels()

	e := initHandlers(app, cfg.EnableInternalApis)

	app.log.Printf("🚀 starting varnamd\nListening on %s", cfg.Address)

	if cfg.EnableSSL {
		if err := e.StartTLS(cfg.Address, cfg.CertFilePath, cfg.KeyFilePath); err != nil {
			app.log.Fatal(err)
		}
	} else {
		if err := e.Start(cfg.Address); err != nil {
			app.log.Fatal(err)
		}
	}
}

func initHandlers(app *App, enableInternalApis bool) *echo.Echo {
	e := echo.New()
	e.GET("/tl/:langCode/:word", handleTransliteration)
	e.GET("/rtl/:langCode/:word", handleReverseTransliteration)
	e.GET("/atl/:langCode/:word", handleAdvancedTransliteration)
	// e.GET("/meta/:langCode:", handleMetadata)
	// e.GET("/download/:langCode/:downloadStart", handleDownload)
	e.GET("/languages", handleLanguages)
	e.GET("/languages/:langCode/download", handleLanguageDownload)
	e.GET("/packs", handlePacks)
	e.GET("/packs/:langCode", handlePacks)
	e.GET("/packs/:langCode/:packIdentifier", handlePackInfo)
	e.GET("/packs/:langCode/:packIdentifier/:packVersionIdentifier", handlePackVersionInfo)
	e.GET("/packs/:langCode/:packIdentifier/:packVersionIdentifier/download", handlePacksDownload)
	e.GET("/status", handleStatus)

	e.GET("/schemes/:schemeID", handleSchemeInfo)
	e.GET("/schemes/:schemeID/definitions", handleSchemeDefinitions)
	e.GET("/schemes/:schemeID/definitions/:letter", handleSchemeLetterDefinitions)

	e.GET("/", handleIndex)

	e.GET("/*", echo.WrapHandler(app.fs.FileServer()))

	if enableInternalApis {
		e.POST("/sync/download/:langCode/enable", handleEnableDownload)
		e.POST("/sync/download/:langCode/disable", handleDisableDownload)

		e.POST("/learn", authUser(handleLearn))
		e.POST("/learn/upload/:langCode", authUser(handleLearnFileUpload))
		e.POST("/train/:langCode", authUser(handleTrain))
		e.POST("/train/bulk/:langCode", authUser(handleTrainBulk))
		e.POST("/delete", authUser(handleDelete))
		e.POST("/packs/download", handlePackDownloadRequest)
	}

	e.Use(middleware.Recover())
	e.Use(middleware.Logger())

	// Custom middleware to set sigleton to app's context.
	e.Use(func(next echo.HandlerFunc) echo.HandlerFunc {
		return func(c echo.Context) error {
			c.Set("app", app)
			return next(c)
		}
	})

	e.Use(middleware.CORSWithConfig(middleware.CORSConfig{
		AllowOrigins: []string{"*"},
		AllowMethods: []string{http.MethodOptions},
	}))

	e.Use(middleware.SecureWithConfig(middleware.SecureConfig{
		XSSProtection:      "",
		ContentTypeNosniff: "",
		XFrameOptions:      "",
		HSTSMaxAge:         3600,
		// ContentSecurityPolicy: "default-src 'self'",
	}))

	// rate limit requests per second (prevent handler exhaustion)
	e.Use(middleware.RateLimiter(middleware.NewRateLimiterMemoryStore(20)))

	return e
}

// authUser as a separate method to apply this middleware only for selected endpoints.
func authUser(next echo.HandlerFunc) echo.HandlerFunc {
	return func(c echo.Context) error {
		var app = c.Get("app").(*App)

		if authEnabled {
			auth := strings.Split(c.Request().Header.Get("Authorization"), " ")
			if len(auth) < 2 {
				app.log.Printf("authorization header not found")
				return echo.NewHTTPError(http.StatusUnauthorized, "authorization header not found")
			}

			if strings.ToLower(auth[0]) != "basic" {
				app.log.Printf("authorization header not found")
				return echo.NewHTTPError(http.StatusUnauthorized, "authorization details not found")
			}

			creds, err := base64.StdEncoding.DecodeString(auth[1])
			if err != nil {
				app.log.Printf("error decoding auth headers, error: %s", err.Error())
				return echo.NewHTTPError(http.StatusUnauthorized, "authorization failed, failed to decode authstring")
			}

			authCreds := strings.Split(string(creds), ":")

			user, ok := users[strings.TrimSpace(authCreds[0])]
			if !ok {
				app.log.Printf("user not found")
				return echo.NewHTTPError(http.StatusUnauthorized, "authorization failed, user not found")
			}

			if user["password"] != strings.TrimSpace(authCreds[1]) {
				app.log.Printf("password mismatch")
				return echo.NewHTTPError(http.StatusUnauthorized, "authorization failed, password mismatch")
			}
		}

		return next(c)
	}
}

