type matches struct {
	Exact       []string
	Possibility []string
}

type schemeDefinitionItem struct {
	Letter      string
	Category    string
	Exact       []string
	Possibility []string
}

type schemeDefinition struct {
	standardResponse
	Details     govarnamgo.SchemeDetails
	Definitions []schemeDefinitionItem
}

func getSchemeDetails(schemeID string) (govarnamgo.SchemeDetails, error) {
	var schemeInfo govarnamgo.SchemeDetails
	foundScheme := false
	for _, sd := range schemeDetails {
		if sd.Identifier == schemeID {
			schemeInfo = sd
			foundScheme = true
		}
	}

	if !foundScheme {
		return schemeInfo, fmt.Errorf("invalid scheme id")
	}

	return schemeInfo, nil
}

func getItemsFromSearchResults(ctx context.Context, searchResults []govarnamgo.Symbol) map[string]matches {
	items := make(map[string]matches)

	for _, r := range searchResults {
		exact := []string{}
		possibility := []string{}

		if r.MatchType == 1 {
			exact = []string{r.Pattern}
		} else {
			possibility = []string{r.Pattern}
		}

		item, ok := items[r.Value1]
		if ok {
			item.Exact = append(item.Exact, exact...)
			item.Possibility = append(item.Possibility, possibility...)
			items[r.Value1] = item
		} else {
			items[r.Value1] = matches{exact, possibility}
		}
	}

	return items
}

func getSchemeDefinitions(ctx context.Context, sd govarnamgo.SchemeDetails) ([]schemeDefinitionItem, error) {
	schemeID := sd.Identifier

	// Vowels
	symbol := govarnamgo.NewSearchSymbol()
	// TODO use constant value from govarnam instead of hardcode
	symbol.Type = 1 // Vowel
	searchResultsI, _ := searchSymbolTable(ctx, schemeID, symbol)
	searchResults := searchResultsI.([]govarnamgo.Symbol)

	items := getItemsFromSearchResults(ctx, searchResults)

	// For sorting map
	keys := make([]string, 0, len(items))
	for k := range items {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var categorizedResult []schemeDefinitionItem

	for _, letter := range keys {
		item := items[letter]
		categorizedResult = append(categorizedResult, schemeDefinitionItem{
			Letter:      letter,
			Category:    searchResults[0].Value1, // അ
			Exact:       item.Exact,
			Possibility: item.Possibility,
		})
	}

	// consonants
	if sd.LangCode == "ml" {
		categorizedResult = append(categorizedResult, getMLConsonants(ctx, sd)...)
	}

	// zwj, virama, other characters
	categorizedResult = append(categorizedResult, getOtherCharacters(ctx, sd)...)

	return categorizedResult, nil
}

func getMLConsonants(ctx context.Context, sd govarnamgo.SchemeDetails) []schemeDefinitionItem {
	letterSets := map[string][]string{
		"ക":          {"ക", "ഖ", "ഗ", "ഘ", "ങ"},
		"ച":          {"ച", "ഛ", "ജ", "ഝ", "ഞ"},
		"ട":          {"ട", "ഠ", "ഡ", "ഢ", "ണ"},
		"ത":          {"ത", "ഥ", "ദ", "ധ", "ന", "ഩ"},
		"പ":          {"പ", "ഫ", "ബ", "ഭ", "മ"},
		"യ":          {"യ", "ര", "ല", "വ", "ശ", "ഷ", "സ", "ഹ", "ള", "ഴ", "റ"},
		"ചില്ലക്ഷരം": {"ൻ", "ർ", "ൽ", "ൾ", "ൺ", "ൿ"},
	}

	items := make(map[string]matches)

	var symbol govarnamgo.Symbol
	symbol.Type = 2 // consonant
	searchResultsI, _ := searchSymbolTable(ctx, sd.Identifier, symbol)
	searchResults := searchResultsI.([]govarnamgo.Symbol)

	for _, r := range searchResults {
		for _, letterSet := range letterSets {
			for _, letter := range letterSet {
				if r.Value1 == letter {
					exact := []string{}
					possibility := []string{}

					if r.MatchType == 1 {
						exact = []string{r.Pattern}
					} else {
						possibility = []string{r.Pattern}
					}

					item, ok := items[r.Value1]
					if ok {
						item.Exact = append(item.Exact, exact...)
						item.Possibility = append(item.Possibility, possibility...)
						items[r.Value1] = item
					} else {
						items[r.Value1] = matches{exact, possibility}
					}
				}
			}
		}
	}

	var categorizedResult []schemeDefinitionItem
	for category, letterSet := range letterSets {
		for _, letter := range letterSet {
			categorizedResult = append(categorizedResult, schemeDefinitionItem{
				Letter:      letter,
				Category:    category,
				Exact:       items[letter].Exact,
				Possibility: items[letter].Possibility,
			})
		}
	}

	return categorizedResult
}

func getSchemeLetterDefinitions(ctx context.Context, sd govarnamgo.SchemeDetails, letter string) ([]schemeDefinitionItem, error) {
	items := make(map[string]matches)

	var symbol govarnamgo.Symbol
	symbol.Value1 = "LIKE " + letter + "%"
	searchResultsI, _ := searchSymbolTable(ctx, sd.Identifier, symbol)
	searchResults := searchResultsI.([]govarnamgo.Symbol)

	for _, r := range searchResults {
		exact := []string{}
		possibility := []string{}

		if r.MatchType == 1 {
			exact = []string{r.Pattern}
		} else {
			possibility = []string{r.Pattern}
		}

		item, ok := items[r.Value1]
		if ok {
			item.Exact = append(item.Exact, exact...)
			item.Possibility = append(item.Possibility, possibility...)
			items[r.Value1] = item
		} else {
			items[r.Value1] = matches{exact, possibility}
		}
	}

	keys := make([]string, 0, len(items))
	for k := range items {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var categorizedResult []schemeDefinitionItem
	for _, letterCombo := range keys {
		item := items[letterCombo]
		letterComboRunes := []rune(letterCombo)
		category := letter
		if len(letterComboRunes) > 2 {
			category = string(letterComboRunes[2])
		}

		categorizedResult = append(categorizedResult, schemeDefinitionItem{
			Letter:      letterCombo,
			Category:    category,
			Exact:       item.Exact,
			Possibility: item.Possibility,
		})
	}

	return categorizedResult, nil
}

func getCategorizedFromSearchResults(ctx context.Context, searchResults []govarnamgo.Symbol, category string) []schemeDefinitionItem {
	var categorizedResult []schemeDefinitionItem
	items := getItemsFromSearchResults(ctx, searchResults)

	for letter, r := range items {
		if category == "" {
			category = letter
		}
		categorizedResult = append(categorizedResult, schemeDefinitionItem{
			Letter:      letter,
			Category:    category,
			Exact:       r.Exact,
			Possibility: r.Possibility,
		})
	}

	return categorizedResult
}

func getOtherCharacters(ctx context.Context, sd govarnamgo.SchemeDetails) []schemeDefinitionItem {
	var categorizedResult []schemeDefinitionItem

	categoryNames := map[int]string{
		6:  "Symbol",
		7:  "Anusvara",
		8:  "Visarga",
		9:  "Virama",
		10: "Other",
		11: "ZWNJ - Zero Width Non Joiner",
		12: "ZWJ - Zero Width Joiner",
		13: "Period",
	}

	i := 6        // Symbol
	for i <= 13 { // to Other symbols
		var symbol govarnamgo.Symbol
		symbol.Type = i
		searchResultsI, _ := searchSymbolTable(ctx, sd.Identifier, symbol)
		searchResults := searchResultsI.([]govarnamgo.Symbol)

		categorizedResult = append(categorizedResult, getCategorizedFromSearchResults(ctx, searchResults, categoryNames[i])...)

		i++
	}

	return categorizedResult
}

package main

import (
	"compress/gzip"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/ioutil"
	"net/http"
	"os"
	"path"
)

// PackVersion Details of a pack version
type PackVersion struct {
	Identifier  string `json:"identifier"` // Pack identifier is unique across all language packs. Example: ml-basic-1
	Version     int    `json:"version"`
	Description string `json:"description"`
	Size        int    `json:"size"`
}

// Pack Details of a pack
type Pack struct {
	Identifier  string        `json:"identifier"`
	Name        string        `json:"name"`
	Description string        `json:"description"`
	LangCode    string        `json:"lang"`
	Versions    []PackVersion `json:"versions"`
}

type packDownload struct {
	Pack     *Pack
	Version  *PackVersion
	FilePath string
}

var packsInfoCached []Pack

func fileExists(filename string) bool {
	info, err := os.Stat(filename)
	if os.IsNotExist(err) {
		return false
	}
	return !info.IsDir()
}

// After a new pack download from upstream, update packs.json with installed packs
func updatePacksInfo(langCode string, pack *Pack, packVersion *PackVersion) error {
	packs, err := getPacksInfo()
	if err != nil {
		return err
	}

	var (
		existingPack *Pack = nil
	)

	for _, packR := range packs {
		if packR.Identifier == pack.Identifier {
			existingPack = &packR
			break
		}
	}

	if existingPack == nil {
		// will have one element
		pack.Versions = []PackVersion{*packVersion}
	} else {
		// Append new pack version
		existingPack.Versions = append(existingPack.Versions, *packVersion)

		pack = existingPack
	}

	// Save pack.json
	packInfoPath := path.Join(getPacksDir(), pack.LangCode, pack.Identifier, "pack.json")
	file, err := json.MarshalIndent(pack, "", "  ")
	if err != nil {
		return err
	}

	err = ioutil.WriteFile(packInfoPath, file, 0644)
	if err != nil {
		return err
	}

	packsInfoCached = nil

	return nil
}

// Download pack from upstream
func downloadPackFile(langCode, packIdentifier, packVersionIdentifier string) (packDownload, error) {
	var (
		pack        *Pack
		packVersion *PackVersion = nil
	)

	packInstalled, _ := getPackVersionInfo(langCode, packIdentifier, packVersionIdentifier)
	if packInstalled != nil {
		return packDownload{}, fmt.Errorf("Pack already installed")
	}

	packInfoURL := fmt.Sprintf("%s/packs/%s/%s", varnamdConfig.upstream, langCode, packIdentifier)

	resp, err := http.Get(packInfoURL)
	if err != nil {
		return packDownload{}, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != 200 {
		respData, err := ioutil.ReadAll(resp.Body)
		if err != nil {
			return packDownload{}, err
		}

		return packDownload{}, fmt.Errorf(string(respData))
	}

	if err = json.NewDecoder(resp.Body).Decode(&pack); err != nil {
		err := fmt.Errorf("Parsing packs JSON failed, err: %s", err.Error())
		return packDownload{}, err
	}

	for _, version := range pack.Versions {
		if version.Identifier == packVersionIdentifier {
			packVersion = &version
			break
		}
	}

	if packVersion == nil {
		return packDownload{}, fmt.Errorf("Pack version not found")
	}

	fileURL := fmt.Sprintf("%s/packs/%s/%s/%s/download", varnamdConfig.upstream, langCode, packIdentifier, packVersionIdentifier)
	fileDir := path.Join(getPacksDir(), langCode, packIdentifier)
	filePath := path.Join(fileDir, packVersionIdentifier)

	if !fileExists(fileDir) {
		os.MkdirAll(fileDir, 0755)
	}

	resp, err = http.Get(fileURL)
	if err != nil {
		return packDownload{}, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != 200 {
		respData, err := ioutil.ReadAll(resp.Body)
		if err != nil {
			return packDownload{}, err
		}

		return packDownload{}, fmt.Errorf(string(respData))
	}

	fz, err := gzip.NewReader(resp.Body)
	if err != nil {
		return packDownload{}, err
	}
	defer fz.Close()

	out, err := os.Create(filePath)
	if err != nil {
		return packDownload{}, err
	}
	defer out.Close()

	// Write the gzip decoded content to file
	_, err = io.Copy(out, fz)

	if err != nil {
		return packDownload{}, err
	}

	return packDownload{Pack: pack, Version: packVersion, FilePath: filePath}, nil
}

func getPackFilePath(langCode, packIdentifier, packVersionIdentifier string) (string, error) {
	if _, err := getPackVersionInfo(langCode, packIdentifier, packVersionIdentifier); err != nil {
		return "", err
	}

	// Example: .varnamd/ml/ml-basic/ml-basic-1.vlf
	packFilePath := path.Join(getPacksDir(), langCode, packIdentifier, packVersionIdentifier) + ".vlf"

	if !fileExists(packFilePath) {
		return "", errors.New("Pack file not found")
	}

	return packFilePath, nil
}

func getPackVersionInfo(langCode string, packIdentifier string, packVersionIdentifier string) (*PackVersion, error) {
	pack, err := getPackInfo(langCode, packIdentifier)

	if err != nil {
		return nil, err
	}

	var packVersion *PackVersion = nil

	for _, version := range pack.Versions {
		if version.Identifier == packVersionIdentifier {
			packVersion = &version
			break
		}
	}

	if packVersion == nil {
		return nil, fmt.Errorf("Pack version not found")
	}

	return packVersion, nil
}

func getPackInfo(langCode string, packIdentifier string) (*Pack, error) {
	packs, err := getPacksLangInfo(langCode)

	if err != nil {
		return nil, err
	}

	for _, pack := range packs {
		if pack.Identifier == packIdentifier {
			return &pack, nil
		}
	}

	return nil, fmt.Errorf("Pack not found")
}

// Get packs by language
func getPacksLangInfo(langCode string) ([]Pack, error) {
	packs, err := getPacksInfo()

	if err != nil {
		return nil, err
	}

	var langPacks []Pack

	for _, pack := range packs {
		if pack.LangCode == langCode {
			langPacks = append(langPacks, pack)
		}
	}

	if len(langPacks) == 0 {
		return nil, fmt.Errorf("No packs found")
	}

	return langPacks, nil
}

func getPacksInfo() ([]Pack, error) {
	if err := createPacksDir(); err != nil {
		err := fmt.Errorf("Failed to create packs directory, err: %s", err.Error())
		return nil, err
	}

	if packsInfoCached != nil {
		return packsInfoCached, nil
	}

	var packsInfo []Pack

	files, err := ioutil.ReadDir(getPacksDir())
	if err != nil {
		return nil, err
	}

	for _, langFolder := range files {
		langFolderPath := path.Join(getPacksDir(), langFolder.Name())
		if langFolder.IsDir() {
			// inside ml
			langFolderFiles, err := ioutil.ReadDir(langFolderPath)

			if err != nil {
				return nil, err
			}

			for _, packFolder := range langFolderFiles {
				if packFolder.IsDir() {
					packInfoPath := path.Join(langFolderPath, packFolder.Name(), "pack.json")
					if fileExists(packInfoPath) {
						var packInfo Pack
						packsFile, _ := ioutil.ReadFile(packInfoPath)

						if err := json.Unmarshal(packsFile, &packInfo); err != nil {
							err := fmt.Errorf("Parsing packs JSON failed, err: %s", err.Error())
							return nil, err
						}

						packsInfo = append(packsInfo, packInfo)
					}
				}
			}
		}
	}

	packsInfoCached = packsInfo

	return packsInfo, nil
}

func createPacksDir() error {
	packsDir := getPacksDir()
	return os.MkdirAll(packsDir, 0750)
}

func getPacksDir() string {
	configDir := getConfigDir()
	return path.Join(configDir, "packs")
}

